import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// issue #12: the customer's discount is applied exactly once.
test('customer discount is applied once (fewer than 10 lines)', () => {
  // 1,000 with a 0.1 discount rate -> 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));

test('bulk discount is applied once, after the customer discount (10 lines)', () => {
  // 10,000 -> 9,000 after the 0.1 customer discount -> 8,550 after the 5% bulk discount
  assert.equal(total(lines(10), 0.1), 8550);
});

test('no bulk discount below 10 lines', () => {
  // 9,000 -> 8,100 after the 0.1 customer discount, no bulk discount
  assert.equal(total(lines(9), 0.1), 8100);
});

test('totals with a discount rate of 0 are unchanged', () => {
  assert.equal(total(lines(9), 0), 9000);
  // 10 lines: only the 5% bulk discount applies
  assert.equal(total(lines(10), 0), 9500);
  assert.equal(total(lines(10)), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
